function mySetInterval(fn, delay) {
  let timer
  let cancelled = false

  function run() {
    if (cancelled) return

    timer = setTimeout(() => {
      fn()
      run()
    }, delay)
  }

  run()

  return {
    cancel() {
      cancelled = true
      clearTimeout(timer)
    }
  }
}

